-- 006 · Catálogo alineado con los servicios de rosaondono.com (26/11/2026) y FAQ por categoría
alter table public.faqs alter column tratamiento_slug drop not null;
alter table public.faqs add column if not exists categoria_slug text references public.categorias(slug);
alter table public.faqs drop constraint if exists faqs_un_destino;
alter table public.faqs add constraint faqs_un_destino check ((tratamiento_slug is null) <> (categoria_slug is null));
grant select on public.faqs to anon;
update public.tratamientos set nombre = 'Rejuvenecimiento facial' where slug = 'tratamiento-facial-antiedad';
update public.tratamientos set nombre = 'Masaje relajante sedativo' where slug = 'masaje-relajante';
update public.tratamientos set nombre = 'Reflexología podal', resumen = 'Presión en puntos concretos de los pies, una técnica tradicional para relajar todo el cuerpo. Sales con las piernas ligeras y la cabeza más tranquila.' where slug = 'reflexologia';
update public.tratamientos set nombre = 'Full face' where slug = 'armonizacion-facial';
update public.tratamientos set nombre = 'Depilación láser diodo y alejandrita', resumen = 'Trabajamos con láser de diodo y de alejandrita y elegimos el más adecuado según tu tipo de piel y de vello. Te explicamos cuántas sesiones calculamos para tu caso antes de empezar.' where slug = 'depilacion-laser';
update public.tratamientos set sesiones = 'Orientativo: entre 6 y 8 sesiones, cada 4 a 6 semanas, según piel, vello y zona' where slug = 'depilacion-laser';
delete from public.faqs where categoria_slug is not null;
